const path = require('node:path');

// Configuration
const gitIgnoreEntries = {
    gitignorePath: path.join(process.cwd(), '.gitignore'),
    filesToAdd: [
        // Generated by render-and-deploy.yml — do not commit build output
        'docs/',
        // Dependencies
        'node_modules/',
        // Logs
        '*.log',
        // Editor / OS temporaries & backups
        '*.bak',
        '*.tmp',
        '.idea',
        '.vscode/',
        // Environment / secrets. A bare `.env*` also matches `.env.example`,
        // and git keeps the last matching rule, so that pattern ignores the
        // template this tool ships. `!.env.example` must stay after `.env.*`.
        '.env',
        '.env.*',
        '!.env.example',
        // Test coverage
        'coverage/',
        // Various caches & history
        '.history/',
        '.cache/',
        // macOS
        '.DS_Store',
        '.AppleDouble',
        '.LSOverride',
        // Windows
        'Thumbs.db',
        'ehthumbs.db',
        'Desktop.ini',
        '$RECYCLE.BIN/',
        '*.lnk',
        // Linux / Ubuntu / general Unix-like
        '*~',
        '.*.swp',
        '.*.swo',
        '.fuse_hidden*',
    ],
    // Dropped on custom-update. `.env*` undoes `!.env.example` above.
    filesToRemove: [
        '.env*',
    ],
};

module.exports = { gitIgnoreEntries };